-- v7: German A1 to B2 course. The week plan is loaded from data/german/course.yaml once and
-- edited on the dashboard afterwards. Quizzes and tests are generated by the Claude API.
CREATE TABLE IF NOT EXISTS german_weeks (
  week       INT PRIMARY KEY,
  phase      TEXT NOT NULL,               -- A1 | A2 | B1 | B2 | Prep
  grammar    TEXT NOT NULL DEFAULT '',
  vocab      TEXT NOT NULL DEFAULT '',
  phrases    TEXT NOT NULL DEFAULT '',
  speaking   TEXT NOT NULL DEFAULT '',
  saturday   TEXT NOT NULL DEFAULT '',
  checkpoint TEXT NOT NULL DEFAULT ''
);

-- one row per course day: the nightly quiz (Mon to Fri; Fri is cumulative)
CREATE TABLE IF NOT EXISTS german_quizzes (
  day          INT PRIMARY KEY,
  week         INT NOT NULL,
  kind         TEXT NOT NULL,             -- daily | friday
  questions    JSONB NOT NULL DEFAULT '[]',
  model        TEXT NOT NULL DEFAULT '',
  status       TEXT NOT NULL DEFAULT 'ready',  -- ready | error
  error        TEXT NOT NULL DEFAULT '',
  generated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS german_quiz_results (
  id          SERIAL PRIMARY KEY,
  day         INT NOT NULL,
  answered_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  score       INT NOT NULL,
  total       INT NOT NULL,
  answers     JSONB NOT NULL DEFAULT '[]'  -- chosen option index per question
);
CREATE INDEX IF NOT EXISTS german_quiz_results_day ON german_quiz_results(day);

-- one row per week: the Saturday written test, the submission, and the marking
CREATE TABLE IF NOT EXISTS german_written (
  week          INT PRIMARY KEY,
  task          JSONB NOT NULL DEFAULT '{}',
  model         TEXT NOT NULL DEFAULT '',
  status        TEXT NOT NULL DEFAULT 'ready',
  error         TEXT NOT NULL DEFAULT '',
  generated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  submission    TEXT NOT NULL DEFAULT '',
  reading_score INT,
  submitted_at  TIMESTAMPTZ,
  marking       JSONB,
  marked_at     TIMESTAMPTZ
);

-- your mistakes, fed back into later quizzes (B2 and Prep draw from here)
CREATE TABLE IF NOT EXISTS german_errors (
  id         SERIAL PRIMARY KEY,
  day        INT NOT NULL DEFAULT 0,
  wrong      TEXT NOT NULL,
  correct    TEXT NOT NULL,
  rule       TEXT NOT NULL DEFAULT '',
  count      INT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (wrong, correct)
);
-- kv keys added: german_course (start_date, exam_target, quiz_design, written_design, statements)
